{
  "storage": {
    "rootDirectory": "/var/lib/registry",
    "dedupe": true,
    "gc": true,
    "gcDelay": "1h",
    "gcInterval": "24h",
    "retention": {
      "dryRun": false,
      "delay": "24h",
      "policies": [
        {
          "repositories": ["**"],
          "deleteReferrers": true,
          "deleteUntagged": true,
          "keepTags": [
            {
              "mostRecentlyPushedCount": 3,
              "mostRecentlyPulledCount": 3,
              "pulledWithin": "168h",
              "pushedWithin": "168h"
            },
            {
              "mostRecentlyPushedCount": 5,
              "mostRecentlyPulledCount": 5
            }
          ]
        }
      ]
    }
  },
  "http": {
    "address": "0.0.0.0",
    "port": "5000",
    "auth": {
      "htpasswd": { "path": "/etc/zot/htpasswd" },
      "failDelay": 1
    },
    "accessControl": {
      "repositories": {
        "**": { "anonymousPolicy": ["read"], "defaultPolicy": [] }
      },
      "adminPolicy": {
        "users": ["oscar"],
        "actions": ["read", "create", "update", "delete"]
      }
    }
  },
  "log": { "level": "info" },
  "extensions": {
    "ui": { "enable": true },
    "search": { "enable": true },
    "scrub": { "enable": true, "interval": "24h" },
    "metrics": { "enable": true, "prometheus": { "path": "/metrics" } },
    "sync": {
      "enable": true,
      "registries": [
        {
          "urls": ["https://index.docker.io"],
          "content": [{ "prefix": "**", "destination": "/docker.io" }],
          "onDemand": true,
          "tlsVerify": true
        },
        {
          "urls": ["https://ghcr.io"],
          "content": [{ "prefix": "**", "destination": "/ghcr.io" }],
          "onDemand": true,
          "tlsVerify": true
        },
        {
          "urls": ["https://quay.io"],
          "content": [{ "prefix": "**", "destination": "/quay.io" }],
          "onDemand": true,
          "tlsVerify": true
        },
        {
          "urls": ["https://registry.k8s.io"],
          "content": [{ "prefix": "**", "destination": "/registry.k8s.io" }],
          "onDemand": true,
          "tlsVerify": true
        }
      ]
    }
  }
}
